function generatePalindromes(s) {
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  let middle = '';
  for (let c = 0; c < 26; c++) {
    if (counts[c] % 2 === 1) {
      if (middle !== '') {
        return [];
      }
      middle = String.fromCharCode(97 + c);
      counts[c]--;
    }
  }
  const halfLength = Math.floor(s.length / 2);
  const half = [];
  const result = [];
  function build() {
    if (half.length === halfLength) {
      const left = half.join('');
      const right = [...half].reverse().join('');
      result.push(left + middle + right);
      return;
    }
    for (let c = 0; c < 26; c++) {
      if (counts[c] === 0) {
        continue;
      }
      counts[c] -= 2;
      half.push(String.fromCharCode(97 + c));
      build();
      half.pop();
      counts[c] += 2;
    }
  }
  build();
  return result;
}

