function generatePalindromes(s) {
  const counts = {};
  for (const ch of s) counts[ch] = (counts[ch] || 0) + 1;
  const odd = Object.keys(counts).filter(ch => counts[ch] % 2 === 1);
  if (odd.length > 1) return [];
  let pool = '';
  for (const ch of Object.keys(counts)) pool += ch.repeat(Math.floor(counts[ch] / 2));
  const found = new Set();
  const permute = (rest, built) => {
    if (rest.length === 0) {
      found.add(built + (odd[0] || '') + built.split('').reverse().join(''));
      return;
    }
    for (let i = 0; i < rest.length; i++) permute(rest.slice(0, i) + rest.slice(i + 1), built + rest[i]);
  };
  permute(pool, '');
  return [...found];
}

