function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letter = (span) => String.fromCharCode(97 + pick(span));
  const shuffle = (chars) => {
    for (let i = chars.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    return chars.join('');
  };
  if (size === 'large') {
    // Six letters, two of them doubled twice: 10,080 palindromes of length 16 keep the output small enough.
    const letters = shuffle('abcdefghijklmnopqrstuvwxyz'.split('')).slice(0, 6);
    return [shuffle([...letters, ...letters, letters[0], letters[0], letters[1], letters[1]])];
  }
  const span = 1 + pick(4);
  if (rand() < 0.35) return [Array.from({ length: 1 + pick(8) }, () => letter(span)).join('')];
  const pairs = pick(5);
  const chars = [];
  for (let i = 0; i < pairs; i++) {
    const ch = letter(span);
    chars.push(ch, ch);
  }
  if (pairs === 0 || rand() < 0.5) chars.push(letter(span));
  return [shuffle(chars)];
}
